      JSON.stringify({ ts: 1000, seq: 0, type: 'session.start', session_id: s3, data: null }),
      JSON.stringify({
        ts: 2000, seq: 1, type: 'session.update', session_id: s3,
        data: {
          iteration: 1,
          update: {
            _meta: { claudeCode: { toolName: 'Bash' } },
