        duration_ms: 1800000,
        event_count: 50,
        iteration_count: 1,
        tasks_completed: 1,
      },
    ];

    const periods = computeTimePeriodStats(summaries, 'day');

    expect(periods).toHaveLength(2);
    // Sorted newest first
    expect(periods[0].period).toBe('2026-01-21');
