        // Derive hint
        if (!isJsonMode()) {
          const refSlug =
            (result.item as LoadedSpecItem).slugs?.[0] ||
            index.shortUlid(result.item._ulid);
          console.log(
            chalk.gray(
              `\nDerive implementation task? kspec derive @${refSlug}`,
