        if (!currentSlugs.includes(options.removeSlug)) {
          error(errors.slug.notFound(options.removeSlug));
          process.exit(EXIT_CODES.ERROR);
        }
        if (currentSlugs.length === 1) {
          error(errors.slug.cannotRemoveLast(options.removeSlug));
          process.exit(EXIT_CODES.ERROR);
        }
