              console.log(chalk.gray(`    Given: ${criterion.given}`));
              console.log(chalk.gray(`    When:  ${criterion.when}`));
              console.log(chalk.gray(`    Then:  ${criterion.then}`));
              console.log();
            }
          }

          console.log(chalk.gray(`${ac.length} acceptance criteria`));
