  it('should allow custom slug', () => {
    const result = kspecJson<{ trait: { slugs: string[] } }>(
      'trait add "Test Trait" --slug test-trait-custom',
      tempDir
    );

    expect(result.trait.slugs).toContain('test-trait-custom');
  });

