   253→    if (!found) {
   254→      // Unknown command — suggest closest
   255→      const suggestion = findClosestCommand(cmd.command, validLeafPaths);
   256→      errors.push({
   257→        index: i,
   258→        id: cmd.id,
   259→        command: cmd.command,
   260→        type: "unknown_command",
   261→        message: `Unknown command: "${cmd.command}"`,
   262→        suggestion: suggestion ?? undefined,
   263→      });
   264→      continue;
   265→    }
   266→
   267→    // Reject command groups (non-leaf nodes)
   268→    if (found.subcommands.length > 0) {
   269→      const suggestion = findClosestCommand(cmd.command, validLeafPaths);
   270→      errors.push({
   271→        index: i,
   272→        id: cmd.id,
   273→        command: cmd.command,
   274→        type: "unknown_command",
   275→        message: `"${cmd.command}" is a command group, not an executable command`,
   276→        suggestion: suggestion ?? undefined,
   277→      });
   278→      continue;
   279→    }
   280→
   281→    // 2. Reject nested batch commands
   282→    // AC: @batch-allowed-commands ac-batch-itself
   283→    if (found.name === "batch") {
   284→      errors.push({
   285→        index: i,
   286→        id: cmd.id,
   287→        command: cmd.command,
   288→        type: "rejected_command",
   289→        message: "Nested batch commands are not allowed",
   290→      });
   291→      continue;
   292→    }
   293→
   294→    // 3. Apply command filter if provided
   295→    // AC: @batch-allowed-commands ac-denylist
   296→    if (options?.commandFilter && !options.commandFilter(found)) {
   297→      errors.push({
   298→        index: i,
   299→        id: cmd.id,
   300→        command: cmd.command,
   301→        type: "rejected_command",
   302→        message: `Command "${cmd.command}" is not allowed in batch mode. Only mutating commands can be used in batch.`,
   303→      });
   304→      continue;
   305→    }
   306→
   307→    // 4. Check for unknown args
   308→    const { names: knownNames, required: requiredNames } =
   309→      getKnownArgNames(found);
   310→
   311→    // Collect all known names as flat array for suggestion matching
   312→    const knownNamesArray = Array.from(knownNames);
   313→
   314→    for (const argKey of Object.keys(cmd.args)) {
   315→      // Accept both kebab-case and camelCase
   316→      if (!knownNames.has(argKey)) {
   317→        const suggestion = findClosestCommand(argKey, knownNamesArray);
   318→        errors.push({
   319→          index: i,
   320→          id: cmd.id,
   321→          command: cmd.command,
   322→          type: "unknown_arg",
   323→          message: `Unknown argument "${argKey}" for command "${cmd.command}"`,
   324→          suggestion: suggestion ?? undefined,
   325→        });
   326→      }
   327→    }
   328→
   329→    // 5. Check for missing required args
   330→    for (const reqName of requiredNames) {
   331→      const camelName = kebabToCamel(reqName);
   332→      if (
   333→        !(reqName in cmd.args) &&
   334→        !(camelName in cmd.args) &&
   335→        // Skip if provided via positional alias
   336→        !Object.keys(cmd.args).some(
   337→          (k) => kebabToCamel(k) === camelName,
   338→        )
   339→      ) {
   340→        errors.push({
   341→          index: i,
   342→          id: cmd.id,
   343→          command: cmd.command,
   344→          type: "missing_required",
   345→          message: `Missing required argument "${reqName}" for command "${cmd.command}"`,
   346→        });
   347→      }
   348→    }
   349→  }
   350→
   351→  return {
   352→    valid: errors.length === 0,
   353→    commands,
   354→    errors,
   355→  };
   356→}
   357→
   358→// ── Error Reporting ─────────────────────────────────────────────────
   359→
   360→/**
   361→ * Format validation errors for human or JSON output.
   362→ *
   363→ * @param result - Validation result containing errors
   364→ * @param json - If true, return JSON string; otherwise human-readable lines
   365→ * @returns Formatted error string
   366→ */
   367→export function reportBatchValidationErrors(
   368→  result: BatchValidationResult,
   369→  json: boolean = false,
   370→): string {
   371→  if (result.valid) {
   372→    return json ? JSON.stringify({ valid: true, errors: [] }) : "";
   373→  }
   374→
   375→  if (json) {
   376→    return JSON.stringify(
   377→      {
   378→        valid: false,
   379→        errors: result.errors,
   380→      },
   381→      null,
   382→      2,
   383→    );
   384→  }
   385→
   386→  // Human-readable format
   387→  const lines: string[] = [];
   388→  for (const err of result.errors) {
   389→    const label = err.id ?? `#${err.index}`;
   390→    lines.push(`[${label}] ${err.message}`);
   391→    if (err.suggestion) {
   392→      lines.push(`  Did you mean: ${err.suggestion}?`);
   393→    }
   394→  }
   395→  return lines.join("\n");
   396→}
   397→
   398→// ── Execution Engine ─────────────────────────────────────────────────
   399→
   400→export interface ExecuteBatchOptions {
   401→  /** Use atomic mode (default true) */
   402→  atomic: boolean;
   403→  /** Continue on error (implies immediate mode) */
   404→  continueOnError: boolean;
   405→  /** Validate-only mode */
   406→  dryRun: boolean;
   407→  /** JSON output */
   408→  json: boolean;
   409→}
   410→
   411→/**
   412→ * Build Commander argv from a BatchCommand and its CommandMeta.
   413→ *
   414→ * Translates { command: "inbox add", args: { content: "hello", tag: ["a","b"] } }
   415→ * into ["inbox", "add", "hello", "--tag", "a", "--tag", "b"]
   416→ *
   417→ * Positional args are emitted in Commander definition order (not JSON key order)
   418→ * to ensure correct argument mapping regardless of how the JSON was serialized.
   419→ */
   420→export function buildCommandArgv(cmd: BatchCommand, cmdMeta: CommandMeta): string[] {
   421→  const argv: string[] = [...cmd.command.trim().split(/\s+/)];
   422→
   423→  // Build sets for classification
   424→  const positionalDefs = cmdMeta.arguments; // ordered by Commander definition
   425→  const positionalNameSet = new Set<string>();
   426→  for (const arg of positionalDefs) {
   427→    positionalNameSet.add(arg.name);
   428→    positionalNameSet.add(kebabToCamel(arg.name));
   429→  }
   430→
   431→  const optionMap = new Map<string, { flags: string; variadic: boolean }>();
   432→  for (const opt of cmdMeta.options) {
   433→    const name = extractOptionName(opt.flags);
   434→    if (name) {
   435→      optionMap.set(name, { flags: opt.flags, variadic: opt.variadic });
   436→      optionMap.set(kebabToCamel(name), { flags: opt.flags, variadic: opt.variadic });
   437→    }
   438→  }
   439→
   440→  // Phase 1: Emit positional args in Commander definition order
   441→  for (const argDef of positionalDefs) {
   442→    const name = argDef.name;
   443→    const camelName = kebabToCamel(name);
   444→    const value = cmd.args[name] ?? cmd.args[camelName];
   445→    if (value === undefined) continue;
   446→
   447→    if (Array.isArray(value)) {
   448→      for (const v of value) argv.push(String(v));
   449→    } else {
   450→      argv.push(String(value));
   451→    }
   452→  }
   453→
   454→  // Phase 2: Emit options from remaining keys
   455→  for (const [key, value] of Object.entries(cmd.args)) {
   456→    const camelKey = kebabToCamel(key);
   457→    // Skip positional args (already emitted)
   458→    if (positionalNameSet.has(key) || positionalNameSet.has(camelKey)) {
   459→      continue;
   460→    }
   461→
   462→    // Convert camelCase key back to kebab-case for CLI
   463→    const kebabKey = key.replace(/[A-Z]/g, (m) => `-${m.toLowerCase()}`);
   464→    const flagName = `--${kebabKey}`;
   465→
   466→    if (typeof value === "boolean") {
   467→      if (value) {
   468→        argv.push(flagName);
   469→      }
   470→      // false booleans: omit (Commander treats absence as false)
   471→    } else if (Array.isArray(value)) {
   472→      // Variadic or repeated options
   473→      for (const v of value) {
   474→        argv.push(flagName, String(v));
   475→      }
   476→    } else if (value !== null && value !== undefined) {
   477→      argv.push(flagName, String(value));
   478→    }
   479→  }
   480→
   481→  return argv;
   482→}
   483→
   484→/**
   485→ * Reset Commander command tree state between dispatches.
   486→ * Commander retains _optionValues between parseAsync calls.
   487→ */
   488→export function resetCommandTree(cmd: Command): void {
   489→  (cmd as any)._optionValues = {};
   490→  (cmd as any)._optionValueSources = {};
   491→  (cmd as any).processedArgs = [];
   492→  for (const sub of cmd.commands) {
   493→    resetCommandTree(sub);
   494→  }
   495→}
   496→
   497→/**
   498→ * Check if a CommandMeta supports the --force option.
   499→ */
   500→function commandHasForce(cmdMeta: CommandMeta): boolean {
   501→  return cmdMeta.options.some((opt) => {
   502→    const name = extractOptionName(opt.flags);
   503→    return name === "force";
   504→  });
   505→}
   506→
   507→/**
   508→ * Execute a batch of commands.
   509→ *
   510→ * AC: @batch-exec ac-default-atomic — atomic mode by default
   511→ * AC: @batch-exec ac-no-atomic-flag — immediate mode with --no-atomic
   512→ * AC: @batch-exec ac-stop-on-error — stop on first failure (default)
   513→ * AC: @batch-exec ac-continue — continue on error with --continue
   514→ * AC: @batch-exec ac-dry-run — validate without executing
   515→ * AC: @batch-exec ac-prevalidate — validation before any execution
   516→ * AC: @batch-exec ac-confirmation-suppressed — auto-append --force
   517→ */
   518→export async function executeBatch(
   519→  commands: BatchCommand[],
   520→  program: Command,
   521→  options: ExecuteBatchOptions,
   522→): Promise<BatchExecResult> {
   523→  const mode: BatchExecMode = options.atomic ? "atomic" : "immediate";
   524→
   525→  // Build command tree for validation
   526→  const tree = extractCommandTree(program);
   527→  const commandFilter = createBatchCommandFilter();
   528→
   529→  // AC: ac-prevalidate — validate all commands before executing any
   530→  const validation = validateBatchCommands(commands, tree, { commandFilter });
   531→  if (!validation.valid) {
   532→    return {
   533→      success: false,
   534→      mode,
   535→      summary: {
   536→        total: commands.length,
   537→        succeeded: 0,
   538→        failed: validation.errors.length,
   539→      },
   540→      results: validation.errors.map((err) => ({
   541→        index: err.index,
   542→        id: err.id,
   543→        command: err.command,
   544→        success: false,
   545→        error: err.message,
   546→      })),
   547→    };
   548→  }
   549→
   550→  // AC: ac-dry-run — validate without executing
   551→  if (options.dryRun) {
   552→    return {
   553→      success: true,
   554→      mode,
   555→      summary: { total: commands.length, succeeded: commands.length, failed: 0 },
   556→      results: commands.map((cmd, i) => ({
   557→        index: i,
   558→        id: cmd.id,
   559→        command: cmd.command,
   560→        success: true,
   561→        output: "dry-run: would execute",
   562→      })),
   563→    };
   564→  }
   565→
   566→  if (options.atomic) {
   567→    return executeAtomic(commands, program, tree, options);
   568→  } else {
   569→    return executeImmediate(commands, program, tree, options);
   570→  }
   571→}
   572→
   573→/**
   574→ * Atomic execution: copy specDir to temp, run all, copy back on success.
   575→ *
   576→ * AC: @batch-exec ac-default-atomic
   577→ * AC: @batch-exec ac-atomic-rollback
   578→ * AC: @batch-exec ac-atomic-isolation
   579→ * AC: @batch-exec ac-single-commit
   580→ */
   581→async function executeAtomic(
   582→  commands: BatchCommand[],
   583→  program: Command,
   584→  tree: CommandMeta,
   585→  options: ExecuteBatchOptions,
   586→): Promise<BatchExecResult> {
   587→  // Get the real context for copy-back
   588→  const ctx = await initContext();
   589→  const realSpecDir = ctx.specDir;
   590→
   591→  // Create temp copy using mkdtemp for safe, collision-free naming
   592→  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "kspec-batch-"));
   593→  await fs.cp(realSpecDir, tempDir, { recursive: true });
   594→
   595→  // Remove .git from temp copy to prevent worktree pointer leaks
   596→  await fs.rm(path.join(tempDir, ".git"), { force: true, recursive: true });
   597→
   598→  // Set up atomic context
   599→  const savedChalkLevel = chalk.level;
   600→  const savedSpecDir = process.env.KSPEC_SPEC_DIR;
   601→  process.env.KSPEC_SPEC_DIR = tempDir;
   602→  setBatchMode(true);
   603→  chalk.level = 0;
   604→
   605→  const results: BatchCommandResult[] = [];
   606→  let allSucceeded = true;
   607→  let copyBackFailed = false;
   608→
   609→  try {
   610→    for (let i = 0; i < commands.length; i++) {
   611→      const cmd = commands[i];
   612→      const result = await dispatchCommand(cmd, i, program, tree);
   613→      results.push(result);
   614→
   615→      if (!result.success) {
   616→        allSucceeded = false;
   617→        // Atomic mode: stop on first failure, discard everything
   618→        // Fill remaining as not-executed
   619→        for (let j = i + 1; j < commands.length; j++) {
   620→          results.push({
   621→            index: j,
   622→            id: commands[j].id,
   623→            command: commands[j].command,
   624→            success: false,
   625→            error: "Not executed (prior command failed in atomic mode)",
   626→          });
   627→        }
   628→        break;
   629→      }
   630→    }
   631→
   632→    // Copy back on success
   633→    if (allSucceeded) {
   634→      try {
   635→        // Clear real specDir contents (except .git and .gitattributes) before copy-back
   636→        const entries = await fs.readdir(realSpecDir);
   637→        for (const entry of entries) {
   638→          if (entry === ".git" || entry === ".gitattributes") continue;
   639→          await fs.rm(path.join(realSpecDir, entry), { recursive: true, force: true });
   640→        }
   641→        // Copy temp contents back
   642→        const tempEntries = await fs.readdir(tempDir);
   643→        for (const entry of tempEntries) {
   644→          await fs.cp(
   645→            path.join(tempDir, entry),
   646→            path.join(realSpecDir, entry),
   647→            { recursive: true },
   648→          );
   649→        }
   650→
   651→        // Single shadow commit for all changes
   652→        if (ctx.shadow?.enabled) {
   653→          const successCount = results.filter((r) => r.success).length;
   654→          await shadowAutoCommit(
   655→            ctx.shadow.worktreeDir,
   656→            `batch: ${successCount} command${successCount !== 1 ? "s" : ""}`,
   657→          );
   658→          shadowPushAsync(ctx.shadow.worktreeDir);
   659→        }
   660→      } catch (copyErr) {
   661→        // Copy-back failed — preserve tempDir for manual recovery
   662→        copyBackFailed = true;
   663→        allSucceeded = false;
   664→        console.error(
   665→          `Batch copy-back failed: ${copyErr instanceof Error ? copyErr.message : copyErr}`,
   666→        );
   667→        console.error(`Temp dir preserved for recovery: ${tempDir}`);
   668→      }
   669→    }
   670→  } finally {
   671→    // Clean up
   672→    setBatchMode(false);
   673→    chalk.level = savedChalkLevel;
   674→    if (savedSpecDir !== undefined) {
   675→      process.env.KSPEC_SPEC_DIR = savedSpecDir;
   676→    } else {
   677→      delete process.env.KSPEC_SPEC_DIR;
   678→    }
   679→    // Only remove temp dir if copy-back succeeded (or commands failed)
   680→    if (!copyBackFailed) {
   681→      await fs.rm(tempDir, { recursive: true, force: true }).catch(() => {});
   682→    }
   683→  }
   684→
   685→  const succeeded = results.filter((r) => r.success).length;
   686→  const failed = results.filter((r) => !r.success).length;
   687→
   688→  return {
   689→    success: allSucceeded,
   690→    mode: "atomic",
   691→    summary: { total: commands.length, succeeded, failed },
   692→    results,
   693→  };
   694→}
   695→
   696→/**
   697→ * Immediate execution: execute against real state, per-command commits.
   698→ *
   699→ * AC: @batch-exec ac-no-atomic-flag
   700→ * AC: @batch-exec ac-immediate-per-commit
   701→ * AC: @batch-exec ac-immediate-no-rollback
   702→ */
   703→async function executeImmediate(
   704→  commands: BatchCommand[],
   705→  program: Command,
   706→  tree: CommandMeta,
   707→  options: ExecuteBatchOptions,
   708→): Promise<BatchExecResult> {
   709→  const savedChalkLevel = chalk.level;
   710→  chalk.level = 0;
   711→
   712→  const results: BatchCommandResult[] = [];
   713→
   714→  try {
   715→    for (let i = 0; i < commands.length; i++) {
   716→      const cmd = commands[i];
   717→      const result = await dispatchCommand(cmd, i, program, tree);
   718→      results.push(result);
   719→
   720→      if (!result.success && !options.continueOnError) {
   721→        // Stop on first failure, remaining not executed
   722→        for (let j = i + 1; j < commands.length; j++) {
   723→          results.push({
   724→            index: j,
   725→            id: commands[j].id,
   726→            command: commands[j].command,
   727→            success: false,
   728→            error: "Not executed (prior command failed)",
   729→          });
   730→        }
   731→        break;
   732→      }
   733→    }
   734→  } finally {
   735→    chalk.level = savedChalkLevel;
   736→  }
   737→
   738→  const succeeded = results.filter((r) => r.success).length;
   739→  const failed = results.filter((r) => !r.success).length;
   740→
   741→  return {
   742→    success: failed === 0,
   743→    mode: "immediate",
   744→    summary: { total: commands.length, succeeded, failed },
   745→    results,
   746→  };
   747→}
   748→
   749→/**
   750→ * Dispatch a single command through Commander's parseAsync.
   751→ */
   752→async function dispatchCommand(
   753→  cmd: BatchCommand,
   754→  index: number,
   755→  program: Command,
   756→  tree: CommandMeta,
   757→): Promise<BatchCommandResult> {
   758→  const parts = cmd.command.trim().split(/\s+/);
   759→  const cmdMeta = findCommand(tree, parts);
   760→  if (!cmdMeta) {
   761→    return {
   762→      index,
   763→      id: cmd.id,
   764→      command: cmd.command,
   765→      success: false,
   766→      error: `Command not found: ${cmd.command}`,
   767→    };
   768→  }
   769→
   770→  // Build argv, auto-appending --force if supported
   771→  // AC: ac-confirmation-suppressed
   772→  const enrichedCmd = { ...cmd, args: { ...cmd.args } };
   773→  if (commandHasForce(cmdMeta) && !("force" in enrichedCmd.args)) {
   774→    enrichedCmd.args.force = true;
   775→  }
   776→  const argv = buildCommandArgv(enrichedCmd, cmdMeta);
   777→
   778→  // Reset Commander state
   779→  resetCommandTree(program);
   780→  setJsonMode(false);
   781→  setVerboseMode(false);
   782→
   783→  const capture = new OutputCapture();
   784→  capture.start();
   785→  installExitInterceptor();
   786→
   787→  let caughtError: unknown = undefined;
   788→  let succeeded = false;
   789→
   790→  try {
   791→    await program.parseAsync(argv, { from: "user" });
   792→    succeeded = true;
   793→  } catch (err) {
   794→    caughtError = err;
   795→  } finally {
   796→    capture.stop();
   797→    uninstallExitInterceptor();
   798→  }
   799→
   800→  if (succeeded) {
   801→    const output = capture.getOutput();
   802→    // Try to parse output as JSON for structured results
   803→    let parsedOutput: unknown = output;
   804→    try {
   805→      parsedOutput = JSON.parse(output);
   806→    } catch {
   807→      // Not JSON, keep as string
   808→    }
   809→
   810→    return {
   811→      index,
   812→      id: cmd.id,
   813→      command: cmd.command,
   814→      success: true,
   815→      output: parsedOutput,
   816→    };
   817→  }
   818→
   819→  // Handle errors
   820→  const err = caughtError;
   821→
   822→  if (err instanceof BatchExitError) {
   823→    // Filter out BatchExitError noise from captured output (handlers may
   824→    // catch and re-log the error before calling process.exit again)
   825→    const capturedOutput = capture
   826→      .getOutput()
   827→      .split("\n")
   828→      .filter((line) => !line.includes("BatchExitError"))
   829→      .join("\n")
   830→      .trim();
   831→
   832→    if (err.code === 0) {
   833→      return {
   834→        index,
   835→        id: cmd.id,
   836→        command: cmd.command,
   837→        success: true,
   838→        output: capturedOutput,
   839→      };
   840→    }
   841→    return {
   842→      index,
   843→      id: cmd.id,
   844→      command: cmd.command,
   845→      success: false,
   846→      error: capturedOutput || `Command exited with code ${err.code}`,
   847→    };
   848→  }
   849→
   850→  // Commander errors (e.g., missing required arg at runtime)
   851→  const isCommanderError =
   852→    err && typeof err === "object" && "code" in err && "exitCode" in err;
   853→  if (isCommanderError) {
   854→    const cmdErr = err as unknown as { message: string; exitCode: number };
   855→    return {
   856→      index,
   857→      id: cmd.id,
   858→      command: cmd.command,
   859→      success: false,
   860→      error: cmdErr.message || capture.getOutput(),
   861→    };
   862→  }
   863→
   864→  // Generic errors
   865→  return {
   866→    index,
   867→    id: cmd.id,
   868→    command: cmd.command,
   869→    success: false,
   870→    error: err instanceof Error ? err.message : String(err),
   871→  };
   872→}
