    75→      const flagsCol = opt.flags.padEnd(30);
    76→      console.log(`  ${chalk.green(flagsCol)} ${opt.description}`);
    77→    }
    78→  }
    79→
    80→  // Conceptual content (curated)
    81→  if (content) {
    82→    if (content.concept.trim()) {
    83→      console.log(chalk.bold("\nDetails:"));
    84→      console.log(content.concept.trim());
    85→    }
    86→
    87→    if (content.examples && content.examples.length > 0) {
    88→      console.log(chalk.bold("\nExamples:"));
    89→      for (const example of content.examples) {
    90→        console.log(chalk.green(`  ${example}`));
    91→      }
    92→    }
    93→
    94→    if (content.seeAlso && content.seeAlso.length > 0) {
    95→      console.log(
    96→        chalk.gray(
    97→          `\nSee also: ${content.seeAlso.map((t) => `kspec help ${t}`).join(", ")}`,
    98→        ),
    99→      );
   100→    }
   101→  }
   102→}
   103→
   104→/**
   105→ * Show help for a concept topic
   106→ */
   107→function showConceptHelp(topic: string, content: HelpContent): void {
   108→  const title = content.title || topic;
   109→  console.log(chalk.bold.cyan(title));
   110→  console.log(chalk.gray("─".repeat(40)));
   111→
   112→  console.log(content.concept.trim());
   113→
   114→  if (content.examples && content.examples.length > 0) {
   115→    console.log(chalk.bold("\nExamples:"));
   116→    for (const example of content.examples) {
   117→      console.log(chalk.green(`  ${example}`));
   118→    }
   119→  }
   120→
   121→  if (content.seeAlso && content.seeAlso.length > 0) {
   122→    console.log(
   123→      chalk.gray(
   124→        `\nSee also: ${content.seeAlso.map((t) => `kspec help ${t}`).join(", ")}`,
   125→      ),
   126→    );
   127→  }
   128→}
   129→
   130→/**
   131→ * Get all available topics (commands + concepts)
   132→ */
   133→function getAllTopics(tree: CommandMeta): string[] {
   134→  const commands = flattenCommandTree(tree)
   135→    .filter((cmd) => cmd.name !== "kspec") // Skip root
   136→    .map((cmd) => cmd.name);
   137→
   138→  const concepts = Object.keys(helpContent).filter(
   139→    (key) => !commands.includes(key),
   140→  );
   141→
   142→  return [...new Set([...commands, ...concepts])];
   143→}
   144→
   145→/**
   146→ * Show list of all topics
   147→ */
   148→function showTopicList(): void {
   149→  const tree = extractCommandTree(program);
   150→
   151→  console.log(chalk.bold.cyan("kspec help"));
   152→  console.log(chalk.gray("─".repeat(40)));
   153→  console.log("\nExtended help for kspec commands and concepts.\n");
   154→
   155→  // Show top-level commands (auto-generated)
   156→  console.log(chalk.bold("Commands:"));
   157→  for (const cmd of tree.subcommands) {
   158→    const nameCol = cmd.name.padEnd(12);
   159→    console.log(`  ${chalk.green(nameCol)} ${cmd.description}`);
   160→  }
   161→
   162→  // Show concept topics (curated)
   163→  console.log(chalk.bold("\nConcepts:"));
   164→  const conceptTopics = Object.keys(helpContent).filter((key) => {
   165→    // Concepts are topics that don't match command names
   166→    return !tree.subcommands.some((cmd) => cmd.name === key);
   167→  });
   168→
   169→  for (const topic of conceptTopics) {
   170→    const content = helpContent[topic];
   171→    const title = content.title || topic;
   172→    const nameCol = topic.padEnd(12);
   173→    console.log(`  ${chalk.green(nameCol)} ${title}`);
   174→  }
   175→
   176→  console.log(chalk.gray("\nUsage: kspec help <topic>"));
   177→  console.log(chalk.gray("       kspec help --all        (full reference)"));
   178→  console.log(chalk.gray("       kspec help --json       (structured output)"));
   179→}
   180→
   181→/**
   182→ * Show full reference (all commands with options)
   183→ */
   184→function showFullReference(): void {
   185→  const tree = extractCommandTree(program);
   186→  const allCommands = flattenCommandTree(tree).filter(
   187→    (cmd) => cmd.name !== "kspec",
   188→  );
   189→
   190→  console.log(chalk.bold.cyan("kspec - Full Command Reference"));
   191→  console.log(chalk.gray("─".repeat(60)));
   192→
   193→  for (const cmd of allCommands) {
   194→    console.log(chalk.bold(`\n${formatCommandUsage(cmd)}`));
   195→    if (cmd.description) {
   196→      console.log(`  ${cmd.description}`);
   197→    }
   198→
   199→    if (cmd.options.length > 0) {
   200→      console.log(chalk.gray("  Options:"));
   201→      for (const opt of cmd.options) {
   202→        console.log(
   203→          chalk.gray(`    ${opt.flags.padEnd(30)} ${opt.description}`),
   204→        );
   205→      }
   206→    }
   207→  }
   208→}
   209→
   210→/**
   211→ * Output help as JSON
   212→ */
   213→function showJson(): void {
   214→  const tree = extractCommandTree(program);
   215→
   216→  // Include both command tree and curated content
   217→  const data = {
   218→    commands: tree,
   219→    content: helpContent,
   220→  };
   221→
   222→  output(data);
   223→}
   224→
   225→/**
   226→ * Show exit codes documentation
   227→ * AC: @cli-schema-introspection ac-2
   228→ */
   229→function showExitCodes(): void {
   230→  console.log(chalk.bold.cyan("kspec - Exit Codes"));
   231→  console.log(chalk.gray("─".repeat(60)));
   232→  console.log("\nExit codes returned by kspec commands:\n");
   233→
   234→  for (const exitCode of EXIT_CODE_METADATA) {
   235→    console.log(chalk.bold(`${exitCode.code} - ${exitCode.name}`));
   236→    console.log(`  ${exitCode.description}`);
   237→    console.log(chalk.gray(`  Commands: ${exitCode.commands}`));
   238→    console.log();
   239→  }
   240→}
   241→
   242→/**
   243→ * Output exit codes as JSON
   244→ * AC: @cli-schema-introspection ac-3
   245→ */
   246→function showExitCodesJson(): void {
   247→  const exitCodesData = EXIT_CODE_METADATA.map((ec) => ({
   248→    code: ec.code,
   249→    name: ec.name,
   250→    description: ec.description,
   251→    commands: ec.commands,
   252→  }));
   253→
   254→  output(exitCodesData);
   255→}
   256→
   257→/**
   258→ * Generate JSON Schema for a command
   259→ * AC: @cli-schema-introspection ac-4
   260→ */
   261→function showCommandJsonSchema(topic: string): void {
   262→  const tree = extractCommandTree(program);
   263→  const command = findCommand(tree, topic.split(" "));
   264→
   265→  if (!command) {
   266→    console.error(chalk.red(`Unknown command: ${topic}`));
   267→    process.exit(EXIT_CODES.NOT_FOUND);
   268→  }
   269→
   270→  // Build JSON Schema object
   271→  const schema: Record<string, unknown> = {
   272→    $schema: "http://json-schema.org/draft-07/schema#",
   273→    type: "object",
   274→    title: `${command.name} command options`,
   275→    description: command.description,
   276→    properties: {},
   277→    required: [],
   278→  };
   279→
   280→  const properties: Record<string, unknown> = {};
   281→  const required: string[] = [];
   282→
   283→  // Add arguments as properties
   284→  for (const arg of command.arguments) {
   285→    const propName = arg.name;
   286→    properties[propName] = {
   287→      type: arg.variadic ? "array" : "string",
   288→      description: arg.description,
   289→    };
   290→
   291→    if (arg.variadic) {
   292→      (properties[propName] as Record<string, unknown>).items = {
   293→        type: "string",
   294→      };
   295→    }
   296→
   297→    if (arg.required) {
   298→      required.push(propName);
   299→    }
   300→  }
   301→
   302→  // Add options as properties
   303→  for (const opt of command.options) {
   304→    // Extract option name from flags (e.g., "-f, --force" -> "force")
   305→    const flagMatch = opt.flags.match(/--([a-zA-Z0-9-]+)/);
   306→    if (!flagMatch) continue;
   307→
   308→    const propName = flagMatch[1];
   309→
   310→    // Determine type from flags
   311→    let type: string = "boolean";
   312→    if (opt.flags.includes("<")) {
   313→      type = "string";
   314→    } else if (opt.flags.includes("[")) {
   315→      type = "string";
   316→    }
   317→
   318→    const propSchema: Record<string, unknown> = {
   319→      type,
   320→      description: opt.description,
   321→    };
   322→
   323→    if (opt.defaultValue !== undefined) {
   324→      propSchema.default = opt.defaultValue;
   325→    }
   326→
   327→    properties[propName] = propSchema;
   328→
   329→    if (opt.required) {
   330→      required.push(propName);
   331→    }
   332→  }
   333→
   334→  schema.properties = properties;
   335→  if (required.length > 0) {
   336→    schema.required = required;
   337→  }
   338→
   339→  output(schema);
   340→}
   341→
   342→/**
   343→ * Register the help command
   344→ */
   345→export function registerHelpCommand(program: Command): void {
   346→  program
   347→    .command("help [topic]")
   348→    .description("Extended help for commands and concepts")
   349→    .option("--all", "Show full command reference")
   350→    .option("--json", "Output as JSON")
   351→    .option("--exit-codes", "Show exit code documentation")
   352→    .option("--json-schema", "Output JSON Schema for command (use with topic)")
   353→    .action((
   354→      topic: string | undefined,
   355→      options: {
   356→        all?: boolean;
   357→        json?: boolean;
   358→        exitCodes?: boolean;
   359→        jsonSchema?: boolean;
   360→      },
   361→    ) => {
   362→      // Handle exit codes flag
   363→      if (options?.exitCodes) {
   364→        // AC: @cli-schema-introspection ac-2, ac-3
   365→        // Note: globalJsonMode is already set by preAction hook if --json flag present
   366→        if (isJsonMode()) {
   367→          showExitCodesJson();
   368→        } else {
   369→          showExitCodes();
   370→        }
   371→        return;
   372→      }
   373→
   374→      // Handle JSON schema flag
   375→      if (options?.jsonSchema) {
   376→        if (!topic) {
   377→          console.error(
   378→            chalk.red("Error: --json-schema requires a command topic"),
   379→          );
   380→          process.exit(EXIT_CODES.USAGE_ERROR);
   381→        }
   382→        // AC: @cli-schema-introspection ac-4
   383→        setJsonMode(true);
   384→        showCommandJsonSchema(topic);
   385→        return;
   386→      }
   387→
   388→      // AC: @cli-schema-introspection ac-1, ac-5
   389→      // If --json flag is present (globalJsonMode set by preAction hook), show JSON
   390→      if (isJsonMode()) {
   391→        showJson();
   392→        return;
   393→      }
   394→
   395→      if (options?.all) {
   396→        showFullReference();
   397→        return;
   398→      }
   399→
   400→      // Show topic or list
   401→      if (topic) {
   402→        showTopic(topic);
   403→      } else {
   404→        showTopicList();
   405→      }
   406→    });
   407→}
