   193→            `Batch failed (${modeLabel}): ${result.summary.succeeded}/${result.summary.total} succeeded, ${result.summary.failed} failed`,
   194→          );
   195→        }
   196→
   197→        // Show per-command results
   198→        for (const r of result.results) {
   199→          const label = r.id ?? `#${r.index}`;
   200→          if (r.success) {
   201→            console.log(`  [${label}] ${r.command}: OK`);
   202→          } else {
   203→            console.error(`  [${label}] ${r.command}: FAILED — ${r.error}`);
   204→          }
   205→        }
   206→      }
   207→
   208→      if (!result.success) {
   209→        process.exit(EXIT_CODES.ERROR);
   210→      }
   211→    });
   212→
   213→  // Register the `batch commands` subcommand
   214→  batchCmd
   215→    .command("commands")
   216→    .description("List commands allowed in batch mode")
   217→    .action(() => {
   218→      const json = isJsonMode();
   219→      const tree = extractCommandTree(program);
   220→      const allCommands = flattenCommandTree(tree);
   221→      const commandFilter = createBatchCommandFilter();
   222→
   223→      // Filter to leaf commands (no subcommands) that pass the batch filter
   224→      const allowedCommands = allCommands.filter((cmd) => {
   225→        // Must be a leaf command (no subcommands)
   226→        if (cmd.subcommands.length > 0) return false;
   227→        // Must pass the batch filter (mutating only)
   228→        if (!commandFilter(cmd)) return false;
   229→        // Exclude batch itself
   230→        if (cmd.name === "batch" || cmd.fullPath.includes("batch")) return false;
   231→        return true;
   232→      });
   233→
   234→      if (json) {
   235→        const commandInfos = allowedCommands.map(buildCommandInfo);
   236→        output({ commands: commandInfos, total: commandInfos.length });
   237→      } else {
   238→        console.log(chalk.bold.cyan("Batch-Allowed Commands"));
   239→        console.log(chalk.gray("─".repeat(60)));
   240→        console.log(chalk.gray("Only mutating commands can be used in batch mode.\n"));
   241→
   242→        for (const cmd of allowedCommands) {
   243→          const signature = formatCommandSignature(cmd);
   244→          console.log(chalk.green(signature));
   245→          if (cmd.description) {
   246→            console.log(chalk.gray(`  ${cmd.description}`));
   247→          }
   248→        }
   249→
   250→        console.log(chalk.gray(`\n${allowedCommands.length} command(s) available`));
   251→      }
   252→    });
   253→}
