export interface ExecuteBatchOptions {
  /** Use atomic mode (default true) */
  atomic: boolean;
  /** Continue on error (implies immediate mode) */
  continueOnError: boolean;
  /** Validate-only mode */
  dryRun: boolean;
  /** JSON output */

