/**
 * Complete result of a batch execution.
 */
export interface BatchExecResult {
  /** Overall success (true only if all commands succeeded) */
  success: boolean;
  /** Execution mode used */
  mode: BatchExecMode;
  /** Aggregate counts */
  summary: BatchExecSummary;
