   717→/**
   718→ * Register validate command
   719→ */
   720→export function registerValidateCommand(program: Command): void {
   721→  program
   722→    .command("validate")
   723→    .description("Validate spec files")
   724→    .option("--schema", "Check schema conformance only")
   725→    .option("--refs", "Check reference resolution only")
   726→    .option("--orphans", "Find orphaned items only")
   727→    .option("--alignment", "Check spec-task alignment")
   728→    .option(
   729→      "--completeness",
   730→      "Check spec completeness (missing AC, descriptions, status inconsistencies)",
   731→    )
   732→    .option("--conventions", "Validate conventions")
   733→    .option(
   734→      "--staleness",
   735→      "Check for stale status mismatches between specs and tasks",
   736→    )
   737→    .option("--skills", "Validate skill files (.claude/skills/*/SKILL.md)")
   738→    .option(
   739→      "--fix",
   740→      "Auto-fix issues where possible (invalid ULIDs, missing timestamps)",
   741→    )
   742→    .option("-v, --verbose", "Show detailed output")
   743→    .option("--strict", "Treat orphans and staleness warnings as errors")
   744→    .action(async (options) => {
   745→      try {
   746→        const ctx = await initContext();
   747→
   748→        if (!ctx.manifestPath) {
   749→          error(validationStrings.noManifest);
   750→          console.log(validationStrings.initHint);
   751→          process.exit(EXIT_CODES.ERROR);
   752→        }
   753→
   754→        // Determine which checks to run
   755→        const runAll =
   756→          !options.schema &&
   757→          !options.refs &&
   758→          !options.orphans &&
   759→          !options.alignment &&
   760→          !options.completeness &&
   761→          !options.conventions &&
   762→          !options.skills;
   763→        const validateOptions = {
   764→          schema: runAll || options.schema,
   765→          refs: runAll || options.refs,
   766→          orphans: runAll || options.orphans,
   767→          completeness: runAll || options.completeness,
   768→        };
   769→
   770→        const result = await validate(ctx, validateOptions);
   771→
   772→        // In strict mode, orphans are errors
   773→        if (options.strict && result.orphans.length > 0) {
   774→          result.valid = false;
   775→        }
   776→
   777→        output(result, () => formatValidationResult(result, options.verbose));
   778→
   779→        // Run auto-fix if requested
   780→        if (options.fix) {
   781→          const filesToFix = await collectFixableFiles(ctx);
   782→          const fixResult = await fixFiles(filesToFix);
   783→          formatFixResult(fixResult);
   784→
   785→          // Re-run validation after fixes to show updated status
   786→          if (fixResult.fixesApplied.length > 0) {
   787→            console.log(validationStrings.revalidating);
   788→            const revalidateResult = await validate(ctx, validateOptions);
   789→            if (revalidateResult.valid) {
   790→              console.log(validationStrings.nowPasses);
   791→            } else {
   792→              console.log(validationStrings.issuesRemain);
   793→            }
   794→            // Update result for exit code
   795→            result.valid = revalidateResult.valid;
   796→            result.schemaErrors = revalidateResult.schemaErrors;
   797→            result.refErrors = revalidateResult.refErrors;
   798→          }
   799→        }
   800→
   801→        // Run alignment check if requested or running all checks
   802→        if (options.alignment || runAll) {
   803→          const tasks = await loadAllTasks(ctx);
   804→          const items = await loadAllItems(ctx);
   805→          const refIndex = new ReferenceIndex(tasks, items);
   806→          const alignmentIndex = new AlignmentIndex(tasks, items);
   807→          alignmentIndex.buildLinks(refIndex);
   808→
   809→          const alignmentWarnings = alignmentIndex.findAlignmentWarnings();
   810→          formatAlignmentWarnings(alignmentWarnings, options.verbose);
   811→
   812→          // Show alignment stats
