   827→            result.completenessWarnings,
   828→            options.verbose,
   829→          );
   830→        }
   831→
   832→        // Run convention validation if requested
   833→        // AC: @convention-definitions ac-3, ac-4
   834→        if (options.conventions) {
   835→          try {
   836→            const metaCtx = await loadMetaContext(ctx);
   837→            if (metaCtx && metaCtx.conventions.length > 0) {
   838→              // For now, we just validate that conventions are well-formed
   839→              // Full validation against actual content (commits, notes, etc.)
   840→              // would require additional content gathering logic
   841→              const conventionResult = validateConventions(
   842→                metaCtx.conventions,
   843→                {},
   844→              );
   845→              formatConventionValidationResult(conventionResult);
   846→
   847→              if (!conventionResult.valid) {
   848→                result.valid = false;
   849→              }
   850→            } else {
   851→              console.log(
   852→                chalk.gray("No conventions defined in meta manifest"),
   853→              );
   854→            }
   855→          } catch (_err) {
   856→            console.log(
   857→              chalk.yellow(
   858→                "Warning: Could not load meta manifest for convention validation",
   859→              ),
   860→            );
   861→          }
   862→        }
   863→
   864→        // Run staleness checks if requested
   865→        // AC: @stale-status-detection ac-4, ac-5
   866→        if (options.staleness) {
   867→          const tasks = await loadAllTasks(ctx);
   868→          const items = await loadAllItems(ctx);
   869→          const refIndex = new ReferenceIndex(tasks, items);
   870→
