        `
items:
  - _ulid: ${testUlid('NOAC')}
    title: "Feature without ACs"
    type: feature
    status:
      implementation: not_started
`
      );

      // Update manifest to include the file
      const manifestPath = path.join(tempDir, 'kynetic.yaml');
