  invalid: [unclosed
\`\`\`
`,
    );

    const result = kspecRun(`plan import "${planPath}" --module @test-core`, tempDir, { expectFail: true });
    expect(result.exitCode).toBe(2); // USAGE_ERROR
    expect(result.stderr).toContain("Malformed YAML");
